def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    normalized_cmd = cmd
    # Fix for https://bugs.python.org/issue8557
    if normalized_cmd and ">" in normalized_cmd:
        normalized_cmd = normalized_cmd[:normalized_cmd.index(">")] + (">",)

    # Fix for windows does not parse shebangs
    if normalized_cmd and normalized_cmd[0].startswith("#!"):
        normalized_cmd = ("",) + normalized_cmd

    # Normalize deep-path shebangs
    shebang_index = next((i for i, cmd_part in enumerate(normalized_cmd) if cmd_part.startswith("#!")), None)
    if shebang_index is not None:
        shebang = normalized_cmd.pop(shebang_index)
        normalized_cmd = (shebang, *normalized_cmd)

    return tuple(normalized_cmd)

