    if not hasattr(self, '__iter__'):
        return str(self)

    output = f"{' ' * indent}{self.__class__.__name__}:\n"
    for key, value in self.__dict__.items():
        if isinstance(value, dict):
            output += f"{' ' * (indent + 4)}{key}:\n"
            output += pretty(value, indent + 4, debug)
        elif isinstance(value, list):
            output += f"{' ' * (indent + 4)}{key}: ["
            for item in value:
                output += pretty(item, indent + 8, debug) if isinstance(item, (dict, list)) else str(item)
                output += ", " if item != value[-1] else ""
            output += "]\n"
        else:
            output += f"{' ' * (indent + 4)}{key}: {pretty(value, indent + 8, debug)}\n"
