class relativedelta:
    def normalized(self):
        days = round(self.days)
        hours = round(self.hours + (self.minutes + self.seconds) / 3600)
        minutes = round((self.minutes + self.seconds) % 3600) / 60
        seconds = (self.minutes + self.seconds) % 60
        return timedelta(days=days, hours=hours, minutes=minutes, seconds=seconds)

