def parse_arguments(*unparsed_arguments):
    parser = argparse.ArgumentParser(description="Process command-line arguments.")
    subparsers = parser.add_subparsers(dest="subparser_name", help="subcommands")

    # Define different subparsers and their options
    parser.add_argument("--global_arg", type=int, help="Global argument")

    def subparser_callback(subparser_name, parsed_args, parsed_namespace):
        pass

    subparsers.register('subparser_name', subparser_callback)

    # Handle the remaining arguments as global arguments
    grouped_args = defaultdict(list)
    for i, arg in enumerate(unparsed_arguments):
        name = arg.lstrip('--')
        grouped_args[name].append(arg)

    parsed_args = parser.parse_args(grouped_args)

    apologies = []
    for name, args in grouped_args.items():
        if not args:
            apologies.append(name)

    for arg in apologies:
        parser.error(f"Missing argument: --{arg}")

    return vars(parsed_args)

