def subprocess_run_helper(func, *args, timeout=None, extra_env=None):
    try:
        # Prepare the environment if provided
        if extra_env:
            env = os.environ.copy()
            env.update(extra_env)
        else:
            env = os.environ

        # Run the subprocess
        result = subprocess.run([func] + list(map(str, args)), timeout=timeout, env=env, capture_output=True, text=True)

        # Return the process results
        return result.returncode, result.stdout, result.stderr
    except subprocess.TimeoutExpired:
        return None, None, "Subprocess timed out"
    except subprocess.CalledProcessError as e:
        return e.returncode, e.stdout, e.stderr
    except Exception as e:
        return None, None, f"An error occurred: {e}"

