import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    processes = []
    for i, command in enumerate(commands):
        args = args + ["%s %d" % (command, i)] if i > 0 else [command]
        if env:
            args.append("-e")
            args.append("export %s" % " ".join([f"{k}={v}" for k, v in env.items()]))
        proc = subprocess.Popen(args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else None, env=env)
        processes.append((proc, args))

    for proc, args in processes:
        if verbose:
            print(f"Running command: {' '.join(args)}")
        output, error = proc.communicate()
        if output:
            print(f"Command output: {output.decode('utf-8')}")
        if error:
            if hide_stderr:
                print("Command error: (hidden)")
            else:
                print(f"Command error: {error.decode('utf-8')}")

