def _verify(iface, candidate, tentative=False, vtype=None):
    if iface not in candidate.providedBy and not tentative:
        raise Invalid("Candidate does not implement the interface using iface.providedBy")

    all_methods = set(iface).difference(set(candidate.providedBy))
    all_attributes = set(iface).difference(set(candidate.providedBy))

    for method in all_methods:
        if not hasattr(candidate, method):
            raise Invalid(f"Method {method} is not defined in candidate")

    for attr in all_attributes:
        if not hasattr(candidate, attr):
            raise Invalid(f"Attribute {attr} is not defined in candidate")

    return True

