    if tentative and iface.providedBy(candidate):
        return True

    implemented_meths = iface.implementedBy(candidate)
    expected_wanted = iface.newContext().implementer(candidate)
    user_meths = set(dir(candidate))
    valid_methods = implemented_meths.intersection(expected_wanted)

    invalid_methods = valid_methods - user_meths
    invalid_attrs = set(iface.fields()).difference(user_meths - expected_wanted)

    if invalid_methods:
        if len(invalid_methods) > 1:
            if len(invalid_methods) == 2:
                raise zope.interface.Invalid(f"Only a single invalid method found: {invalid_methods[0]}")
