        if len(invalid_methods) == 1:
            raise zope.interface.Invalid(f"Invalid method: {invalid_methods[0]}")
        else:
            raise zope.interface.Invalid("No invalid methods found.")

    if invalid_attrs:
        if len(invalid_attrs) > 1:
            if len(invalid_attrs) == 2:
