def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    ignore_tags_in_code = False
    current_tag = None
    current_tag_area = ""

    for char in text:
        if char == '<':
            ignore_tags_in_code = True
            current_tag_area = ""
            current_tag = ""
        elif char == '>':
            if not ignore_tags_in_code:
                tags.add(current_tag)
            if replacer:
                current_tag_area = replacer(current_tag)
            current_tag = ""
            ignore_tags_in_code = False
        elif not ignore_tags_in_code and char.isalnum():
            current_tag += char
            current_tag_area += char

    return tags, current_tag_area

