def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Define a dictionary to hold the plugin's properties
    plugin_spec_dict = {}

    # Iterate through each file in the plugin directory
    for filename in os.listdir(plugin_dir):
        if filename.endswith('.json'):
            # Read the JSON file and load it as a dictionary
            with open(os.path.join(plugin_dir, filename), 'r') as file:
                data = json.load(file)

            # Merge the loaded data into the plugin_spec_dict
            plugin_spec_dict.update(data)

    # Flatten the dictionary by recursively traversing its values
    def flatten_dict(d, parent_key='', sep='/'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    items.extend(flatten_dict({f"{new_key}_{i}": item}, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    # Flatten the dictionary
    flattened_dict = flatten_dict(plugin_spec_dict)

    return flattened_dict

